#include <bits/stdc++.h>
using namespace std;

int main() {
    ios::sync_with_stdio(false);
    cin.tie(nullptr);
    int n, m;
    cin >> n >> m;
    vector<int> a(n);
    for (int i = 0; i < n; ++i) {
        cin >> a[i];
    }

    int n1 = n / 2;
    vector<long long> a1, a2;

    function<void(int, long long)> generate_sums1 = [&](int i, long long current_sum) {
        if (i == n1) {
            a1.push_back(current_sum);
        } else {
            generate_sums1(i + 1, (current_sum + a[i]) % m);
            generate_sums1(i + 1, current_sum);
        }
    };

    function<void(int, long long)> generate_sums2 = [&](int i, long long current_sum) {
        if (i == n) {
            a2.push_back(current_sum);
        } else {
            generate_sums2(i + 1, (current_sum + a[i]) % m);
            generate_sums2(i + 1, current_sum);
        }
    };

    generate_sums1(0, 0);
    generate_sums2(n1, 0);

    sort(a1.begin(), a1.end());
    a1.erase(unique(a1.begin(), a1.end()), a1.end());

    long long ans = 0;
    for (auto i : a2) {
        auto j = std::lower_bound(a1.begin(), a1.end(), m - i);
        if (j != a1.begin()) {
            --j;
            long long candidate = *j + i;
            if (candidate > ans) {
                ans = candidate;
            }
        }
    }
    cout << ans << "\n";
    return 0;
}
